from collections import Counter
def solve(grid):
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    # scattered cells: color appearing many times, isolated
    # object: cells of a color appearing few times... find object via colors with count<= some
    # collect non-bg cells that are adjacent to at least one other non-bg cell -> object
    cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]!=bg]
    obj=set()
    for (i,j) in cells:
        if any((i+di,j+dj) in set(cells) for di in (-1,0,1) for dj in (-1,0,1) if (di,dj)!=(0,0)):
            obj.add((i,j))
    # expand: object may not be fully adjacent? use connected comp of any non-scattered... take cells with >=1 neighbor
    scat=[(i,j) for (i,j) in cells if (i,j) not in obj]
    ocolor=Counter(grid[i][j] for i,j in obj).most_common(1)[0][0]
    # full bbox of object
    rs=[i for i,j in obj]; cs=[j for i,j in obj]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    cr,cc=(r0+r1)//2,(c0+c1)//2
    out=[row[:] for row in grid]
    for i,j in scat:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if (r,c) in obj:
                    ii,jj=i+(r-cr),j+(c-cc)
                    if 0<=ii<h and 0<=jj<w: out[ii][jj]=grid[r][c]
    return out

